css:
.print-format { page-width: 150mm; page-height: 100mm; margin: 4mm; padding: 0; font-size: 11px; }
.tm-carton { page-break-after: always; border: 2px solid #000; padding: 6px 8px; height: 88mm; box-sizing: border-box; }
.tm-carton:last-child { page-break-after: auto; }
.tm-carton .row1 { display: flex; justify-content: space-between; border-bottom: 1px solid #000; padding-bottom: 4px; }
.tm-carton .marks { white-space: pre-line; font-weight: 700; font-size: 12px; }
.tm-carton .cno { font-size: 22px; font-weight: 800; text-align: right; }
.tm-carton table { width: 100%; border-collapse: collapse; margin-top: 4px; }
.tm-carton td { padding: 1px 3px; }
.tm-carton td.k { color: #444; width: 26%; }
.tm-carton .sscc { text-align: center; margin-top: 4px; }
.tm-carton .sscc svg { height: 22mm; width: auto; max-width: 100%; }
